from __future__ import annotations

"""TrialLens investigator evaluation on Chalk (generated by build_investigator_eval.py; do not edit by hand).

Task:    ti_check(answer_json, graph_json, review_json, offline_json) -> {"rejected", "failed_checks", "n_checks"}
         = check_answer() from trialforge/investigate.py, inlined verbatim with trialforge/verifier.py.
Scorers: mutant_rejected        - mutant rows: 1.0 if check_answer rejects the answer (any failed check)
         expected_check_failed  - mutant rows: 1.0 if the check the mutant targets is among the failures
         base_not_rejected      - base rows: 1.0 if the deterministic answer passes
         control_not_rejected   - control rows (a verbatim quote appended): 1.0 if it passes
         valid-json             - built-in json_valid

Documents: quote lookups (protocol PDF, ClinicalTrials.gov eligibility text, FDA guidance) were resolved
locally from the cached documents when the dataset was built and are frozen per row in offline_json; a
lookup missing from the table counts as "could not check" (warn), never as a pass. Every other check
(evidence ids, stance, numbers, NCT ids, language, counterevidence, verifier.verify on structured
claims) runs here. The developers wrote both the mutants and the checker.

Local dry run (no Chalk import, no deployment):  ../.venv/bin/python triallens_investigator_eval.py
Remote run (after `chalk login`; the user confirms):  ../.venv/bin/python triallens_investigator_eval.py --run
Decorating a function with chalkcompute.function outside a Chalk container starts a deployment, so the
functions are decorated only with --run or inside the Chalk container.
"""
import json
import os
import sys

# ----------------------------------------------------------------------------- inlined verifier
# <<VERIFIER_SOURCE>>

# ----------------------------------------------------------------------------- inlined check_answer
# <<CHECK_SOURCE>>


# ----------------------------------------------------------------------------- frozen document lookups
def _offline_resolvers(off):
    def protocol_quote(n, q):
        return off.get("protocol_quote", {}).get(n, {}).get(_norm(q))

    def registry_quote(n, q):
        return off.get("registry_quote", {}).get(n, {}).get(_norm(q))

    def fda_quote(g, q):
        ok = off.get("fda_quote", {}).get(str(g), {}).get(_norm(q))
        return {"ok": ok} if ok is not None else {"ok": None, "reason": "lookup not in the frozen table"}

    def guidance_key(node):
        return off.get("guidance_by_key", {}).get(str((node.get("data") or {}).get("key")))

    return {"protocol_quote": protocol_quote, "registry_quote": registry_quote, "fda_quote": fda_quote, "guidance_key": guidance_key}


def _deploying() -> bool:
    if "--run" in sys.argv:
        return True
    return bool(os.environ.get("CHALK_REMOTE_FUNCTION"))  # chalkcompute._function._REMOTE_ENV_VAR (inside the container)


# ----------------------------------------------------------------------------- task and scorers
def ti_check(answer_json: str, graph_json: str, review_json: str, offline_json: str) -> str:
    checks = check_answer(json.loads(answer_json), json.loads(graph_json), json.loads(review_json),
                          _offline_resolvers(json.loads(offline_json)))
    failed = sorted({c["check"] for c in checks if c["result"] == "fail"})
    return json.dumps({"rejected": bool(failed), "failed_checks": failed, "n_checks": len(checks)})


def _scored(x: float) -> list:
    return [chalkcompute.EvaluationScorerResult(score=x)] if _deploying() else [x]


def mutant_rejected(kind: str, output: str) -> list[chalkcompute.EvaluationScorerResult]:
    if kind != "mutant":
        return []
    return _scored(1.0 if json.loads(output)["rejected"] else 0.0)


def expected_check_failed(kind: str, expected_check: str, output: str) -> list[chalkcompute.EvaluationScorerResult]:
    if kind != "mutant":
        return []
    return _scored(1.0 if expected_check in json.loads(output)["failed_checks"] else 0.0)


def base_not_rejected(kind: str, output: str) -> list[chalkcompute.EvaluationScorerResult]:
    if kind != "base":
        return []
    return _scored(0.0 if json.loads(output)["rejected"] else 1.0)


def control_not_rejected(kind: str, output: str) -> list[chalkcompute.EvaluationScorerResult]:
    if kind != "control":
        return []
    return _scored(0.0 if json.loads(output)["rejected"] else 1.0)


SCORER_NAMES = ["mutant_rejected", "expected_check_failed", "base_not_rejected", "control_not_rejected"]

if _deploying():
    import chalkcompute

    ti_check = chalkcompute.function(ti_check)
    mutant_rejected = chalkcompute.function(mutant_rejected)
    expected_check_failed = chalkcompute.function(expected_check_failed)
    base_not_rejected = chalkcompute.function(base_not_rejected)
    control_not_rejected = chalkcompute.function(control_not_rejected)
    valid_json = chalkcompute.scorers.json_valid(name="valid-json")


def _expected_ok(kind: str, out: dict) -> bool:
    return out["rejected"] if kind == "mutant" else not out["rejected"]


if __name__ == "__main__":
    import argparse
    import time
    from pathlib import Path

    ap = argparse.ArgumentParser()
    ap.add_argument("--run", action="store_true")
    args = ap.parse_args()
    rows = [json.loads(line) for line in (Path(__file__).parent / "investigator_dataset.jsonl").read_text().splitlines()]
    if not args.run:
        good, same = 0, 0
        for r in rows:
            out = json.loads(ti_check(r["answer_json"], r["graph_json"], r["review_json"], r["offline_json"]))
            good += _expected_ok(r["kind"], out)
            same += out["rejected"] == r["local_rejected"]
            if not _expected_ok(r["kind"], out):
                print("MISMATCH", r["case_id"], out["failed_checks"])
        print(f"local dry run: {good}/{len(rows)} verdicts as expected; {same}/{len(rows)} identical to the full local check")
        sys.exit(0)

    scorers = [mutant_rejected, expected_check_failed, base_not_rejected, control_not_rejected, valid_json]
    dataset = chalkcompute.DatasetClient().upload("triallens-investigator-cases", rows)
    evaluation = chalkcompute.Evaluation.create("triallens-investigator", dataset=dataset, task=ti_check, scorers=scorers)
    run = evaluation.run(metadata={"suite": "investigator", "n_cases": len(rows)}).wait()
    ids = {k: str(getattr(x, a, "")) for k, x, a in (("evaluation_id", evaluation, "id"), ("run_id", run, "id"), ("result_dataset", run, "result_dataset"))}
    table = chalkcompute.DatasetClient().read(run.result_dataset)
    recs = table.to_pylist()
    by_kind = {}
    task_errors = 0
    for r in recs:
        try:
            out = json.loads(r.get("output")) if r.get("output") else None
        except Exception:
            out = None
        if out is None:
            task_errors += 1
            continue
        k = by_kind.setdefault(r.get("kind"), {"rows": 0, "as_expected": 0})
        k["rows"] += 1
        k["as_expected"] += _expected_ok(r.get("kind"), out)
    summary = {"evaluation": "triallens-investigator", "status": str(run.status), "rows": len(recs), **ids,
               "task_errors": task_errors, "by_kind": by_kind, "scorers_in_order": SCORER_NAMES + ["valid-json"],
               "note": "The developers wrote both the mutants and the checker.",
               "ran_at": time.strftime("%Y-%m-%d %H:%M:%S")}
    print(json.dumps(summary, indent=1))
    (Path(__file__).parent.parent / "data" / "chalk_investigator_eval_run.json").write_text(json.dumps(summary, indent=1))
